-- ALPHA service/admin content payloads.
-- Safe to run after deploying the matching code. Re-runnable; refreshes service copy to current frontend defaults.
SET NAMES utf8mb4;

START TRANSACTION;

SET @ac_service_user_id := (SELECT id FROM users ORDER BY id LIMIT 1);

-- services_index / services
INSERT INTO content_service_pages (code, template_key, is_active, published_at, sort_order, payload, created_by, updated_by, created_at, updated_at)
VALUES ('services', 'services_index', 1, NOW(), 0, JSON_EXTRACT('[]', '$'), @ac_service_user_id, @ac_service_user_id, NOW(), NOW())
ON DUPLICATE KEY UPDATE
    id = LAST_INSERT_ID(id),
    template_key = VALUES(template_key),
    is_active = VALUES(is_active),
    published_at = COALESCE(published_at, VALUES(published_at)),
    sort_order = VALUES(sort_order),
    payload = VALUES(payload),
    updated_by = @ac_service_user_id,
    updated_at = NOW();
SET @ac_service_services_index_id := LAST_INSERT_ID();

INSERT INTO content_service_page_translations (service_page_id, locale, title, slug, meta_title, meta_description, payload, created_at, updated_at)
VALUES (@ac_service_services_index_id, 'hr', 'Usluge', 'usluge', 'Usluge', 'Pregled usluga ALPHA CAPITALISA: revizija, računovodstvo i poslovno savjetovanje.', JSON_EXTRACT('{"video_section":{"title":"","intro":""},"showcase":{"title_lead":"Naše usluge","title_accent":"","intro":"Kroz integrirani pristup reviziji, računovodstvu i financijskom savjetovanju stvaramo dodatnu vrijednost pomažući klijentima da posluju sigurnije, transparentnije i učinkovitije.","outro":["Kroz integrirani pristup reviziji, računovodstvu i financijskom savjetovanju stvaramo dodatnu vrijednost za klijente koji žele stabilan rast, jasnije odluke i pouzdanu podršku u ključnim poslovnim trenucima.","Naša podrška omogućuje bolje upravljanje financijama, kvalitetnije strateško planiranje i sigurnije donošenje odluka."]},"primary_pillars":[{"key":"audit","title":"Revizija","subtitle":"sigurnost i povjerenje u brojke","text":"Neovisna provjera financijskih izvještaja koja povećava povjerenje vlasnika, investitora i partnera.","bullets":["Pomažemo vlasnicima, investitorima i upravi da imaju potpunu sigurnost u financijske izvještaje.","Revizija smanjuje rizik pogrešnih odluka jer potvrđuje da su podaci točni, potpuni i u skladu s propisima.","Kroz neovisnu provjeru dobivate jasnu sliku stvarnog financijskog stanja poduzeća, što jača povjerenje banaka, partnera i regulatora."],"url":"/revizija","action_label":"Detaljnije"},{"key":"accounting","title":"Računovodstvo","subtitle":"kontrola i jasnoća poslovanja","text":"Precizno vođenje knjiga i pravovremeno izvještavanje koje oslobađa menadžment za strateške odluke.","bullets":["Omogućujemo da vaše poslovanje bude financijski uredno, pregledno i uvijek spremno za odluke.","To znači da u svakom trenutku imate točne podatke o prihodima, troškovima i rezultatu, bez kašnjenja i nejasnoća.","Umjesto da reagirate na probleme, možete upravljati poslovanjem na temelju pouzdanih informacija."],"url":"/racunovodstvo","action_label":"Detaljnije"},{"key":"advisory","title":"Savjetovanje","subtitle":"rast, optimizacija i bolji financijski izbor","text":"Financijsko i porezno savjetovanje te pribavljanje kapitala - sve na jednom mjestu.","bullets":["Pomažemo društvima, investitorima i poduzetnicima u donošenju kvalitetnih odluka, upravljanju rizicima i stvaranju dugoročne vrijednosti.","Pružamo podršku u procjenama vrijednosti, due diligence postupcima, M&A procesima i strukturiranju financiranja.","EU fondovi, bankovni krediti i porezne olakšice povezani su u okviru pribavljanja financiranja."],"url":"/savjetovanje","action_label":"Detaljnije"}]}', '$'), NOW(), NOW())
ON DUPLICATE KEY UPDATE
    title = VALUES(title),
    slug = VALUES(slug),
    meta_title = VALUES(meta_title),
    meta_description = VALUES(meta_description),
    payload = VALUES(payload),
    updated_at = NOW();

INSERT INTO content_service_page_translations (service_page_id, locale, title, slug, meta_title, meta_description, payload, created_at, updated_at)
VALUES (@ac_service_services_index_id, 'en', 'Services', 'services', 'Services', 'Overview of ALPHA CAPITALIS services: audit, accounting, and business advisory.', JSON_EXTRACT('{"video_section":{"title":"","intro":""},"showcase":{"title_lead":"Our services","title_accent":"","intro":"Through an integrated approach to audit, accounting, and financial advisory, we create value by helping clients operate with more confidence, transparency, and efficiency.","outro":["Our support helps companies manage finance more clearly, plan strategically, and make safer decisions in key business moments."]},"primary_pillars":[{"key":"audit","title":"Audit","subtitle":"assurance and confidence in the numbers","text":"Independent review of financial statements that increases confidence for owners, investors, and partners.","bullets":["We help owners, investors, and management gain confidence in financial statements.","Audit reduces the risk of wrong decisions by confirming that data is accurate, complete, and compliant.","Through independent review you gain a clear view of the company financial position, strengthening trust with banks, partners, and regulators."],"url":"/revizija","action_label":"Learn more"},{"key":"accounting","title":"Accounting","subtitle":"control and clarity of operations","text":"Precise bookkeeping and timely reporting that frees management for strategic decisions.","bullets":["We help keep your business financially organized, transparent, and ready for decisions.","That means accurate data on revenue, costs, and results at any moment, without delays or uncertainty.","Instead of reacting to problems, you can manage the business based on reliable information."],"url":"/racunovodstvo","action_label":"Learn more"},{"key":"advisory","title":"Advisory","subtitle":"growth, optimization and better financial choices","text":"Financial and tax advisory plus capital raising - all in one place.","bullets":["We help companies, investors, and entrepreneurs make better decisions, manage risk, and create long-term value.","We support valuations, due diligence, M&A processes, and financing structuring.","EU funds, bank loans, and tax incentives are connected within the capital raising framework."],"url":"/savjetovanje","action_label":"Learn more"}]}', '$'), NOW(), NOW())
ON DUPLICATE KEY UPDATE
    title = VALUES(title),
    slug = VALUES(slug),
    meta_title = VALUES(meta_title),
    meta_description = VALUES(meta_description),
    payload = VALUES(payload),
    updated_at = NOW();

-- audit / audit
