VALUES ('tax', 'tax', 1, NOW(), 110, JSON_EXTRACT('{"blog_source":{"mode":"auto_category","category_id":null,"post_ids":[],"limit":6},"video_source":{"items":[]}}', '$'), @ac_service_user_id, @ac_service_user_id, NOW(), NOW())
